func (s SameDirect) JSONSize() int {
	size := 208
	if s.Addr.Is4() {
		size += 15
	} else {
		size += 39
	}
	if z := len(s.Addr.Zone()); z > 0 {
		size += 1 + z*2
	}
	size += len(s.ByKey) * 4
	for k, v := range s.ByKey {
		size += len(k) * 2
		size += 2
		if v.IP.To4() != nil {
			size += 18
		} else {
			size += 43
		}
	}
	if n := len(s.Durs); n > 0 {
		size += n - 1
	}
	size += len(s.Durs) * 27
	if n := len(s.Nets); n > 0 {
		size += n - 1
	}
	for i0 := range s.Nets {
		size += 2
		if s.Nets[i0].IP.To4() != nil {
			size += 18
		} else {
			size += 43
		}
	}
	size += len(s.NS.String) * 2
	if s.PInt == nil {
		size += 4
	} else {
		size += 20
	}
	if s.PTCP == nil {
		size += 4
	} else {
		size += 2
		if (*s.PTCP).IP.To4() != nil {
			size += 21
		} else {
			size += 47
		}
		if z := len((*s.PTCP).Zone); z > 0 {
			size += 1 + z*2
		}
	}
	if s.TCP.IP.To4() != nil {
		size += 21
	} else {
		size += 47
	}
	if z := len(s.TCP.Zone); z > 0 {
		size += 1 + z*2
	}
	if s.UDP.IP.To4() != nil {
		size += 21
	} else {
		size += 47
	}
	if z := len(s.UDP.Zone); z > 0 {
		size += 1 + z*2
	}
	size += len(s.URL.Scheme) + len(s.URL.Host)*3 + len(s.URL.Path)*3 + len(s.URL.RawQuery)*2 + len(s.URL.Fragment)*3 + len(s.URL.Opaque)*2
	if s.URL.User != nil {
		pw, _ := s.URL.User.Password()
		size += (len(s.URL.User.Username())+len(pw))*3 + 2
	}
	if n := len(s.Words); n > 0 {
		size += n - 1
	}
	for i0 := range s.Words {
		size += len(s.Words[i0])*2 + 2
	}
	return size
}

